  const panel=(title,body,actions='')=>`<section class="card aw-panel"><div class="card-h"><h2>${esc(title)}</h2><div class="aw-actions">${actions}</div></div>${body}</section>`;
  const kv=(label,value)=>`<div><span>${esc(label)}</span><b>${esc(value||'—')}</b></div>`;
  const table=(heads,rows)=>{if(heads[0]!=='序号'){heads=['序号',...heads];rows=rows.map((r,i)=>[i+1,...r]);}return `<div class="aw-table-scroll"><table class="aw-table"><thead><tr>${heads.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map((r,i)=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${heads.length}" class="empty">暂无记录</td></tr>`}</tbody></table></div>`;}
  function open(k,id){const r=get(k,id);if(!r||!visible(r)){toast('当前身份无权访问该事项');return;}if(state.page!=='audit-record'||ui.id!==id)ui.history.push({route:state.page,key:ui.key,id:ui.id,tab:ui.tab,page:ui.page,query:ui.query,status:ui.status});ui.key=k;ui.id=id;ui.tab='业务详情';state.page='audit-record';state.activeNavProcess='audit:'+k;log(r,'查看','打开业务工作区');render();window.scrollTo(0,0);}
  function back(){const old=ui.history.pop();if(old){state.page=old.route;Object.assign(ui,{key:old.key,id:old.id,tab:old.tab,page:old.page,query:old.query,status:old.status});}else state.page='audit-'+ui.key;render();}
  function resolve(id){for(const [k,rows] of Object.entries(store.records)){const r=rows.find(r=>r.id===id||r.id==='HT-'+id.replace('CTR-',''));if(r){open(k,r.id);return true;}}const risk=store.risks.find(r=>r.id===id);if(risk){const q=records('riskQuarter').find(x=>x.riskId===id);if(q)open('riskQuarter',q.id);else{state.page='risk';ui.id=id;render();}return true;}return false;}
  function link(id){return id?`<button class="link" onclick="AuditWorkspace.resolve('${esc(id)}')">${esc(id)}</button>`:'—';}
  function deadline(r){const days=Math.ceil((new Date(r.due+'T00:00:00')-new Date(config.date+'T00:00:00'))/86400000);return /已批准|已签署|已生效|已停用|历史版本|已关闭|已销账|已归档|已终止/.test(r.status)?'已办结':days<0?'超期'+(-days)+'天':days<=config.warningDays?'临期'+days+'天':'正常';}
  function list(k){if(ui.key!==k){ui.key=k;ui.query='';ui.status='全部状态';ui.page=1;}const d=defs[k],all=records(k).filter(visible).filter(r=>[r.id,r.title,r.owner,r.department].join(' ').includes(ui.query));const filtered=all.filter(r=>ui.status==='全部状态'||(ui.status==='临期/超期'?deadline(r)!=='正常'&&deadline(r)!=='已办结':r.status===ui.status));const max=Math.max(1,Math.ceil(filtered.length/ui.size));ui.page=Math.min(ui.page,max);const rows=filtered.slice((ui.page-1)*ui.size,ui.page*ui.size);const statuses=[...new Set(all.map(r=>r.status))];
    const stats=['全部状态','临期/超期',...statuses.slice(0,2)].map(s=>`<button class="stat ${ui.status===s?'active':''}" onclick="AuditWorkspace.filter('${s}')"><b>${s==='全部状态'?all.length:s==='临期/超期'?all.filter(r=>/临期|超期/.test(deadline(r))).length:all.filter(r=>r.status===s).length}</b><span>${s==='全部状态'?'全部事项':esc(s)}</span></button>`).join('');
    const columns=({contractReview:['相对方','合同金额'],contractTemplate:['适用合同','当前版本'],contractSeal:['关联合同','签署方式'],contractChange:['原合同','变更后金额'],contractTermination:['原合同','处理类型'],contractPerformance:['关联合同','履约节点'],compliance:['适用范围','清单版本'],legal:['对方当事人','费用累计'],riskQuarter:['报告季度','人工等级'],riskRectify:['关联风险','验收标准'],riskFeedback:['关联风险','整改进度'],riskEvent:['发生时间','首报状态'],auditRectify:['审计来源','整改计划'],procurement:['SRM项目','监督节点'],procurementRectify:['来源监督','整改要求']})[k];
    function values(r){return ({contractReview:[esc(r.party),money(r.amount)],contractTemplate:[esc(r.contractType),esc(r.version)],contractSeal:[link(r.contractId),esc(r.signMode)],contractChange:[link(r.contractId),money(r.newAmount)],contractTermination:[link(r.contractId),esc(r.operation)],contractPerformance:[link(r.contractId),esc(r.milestone)],compliance:[esc(r.scope),esc(r.version)],legal:[esc(r.party),money((r.expenses||[]).reduce((a,e)=>a+Number(e.amount),0))],riskQuarter:[esc(r.quarter),badge(r.level||'待评估')],riskRectify:[link(r.riskId),esc(r.acceptance)],riskFeedback:[link(r.riskId),(r.progress||0)+'%'],riskEvent:[esc(r.occurred),r.reportedAt?'已首报':(new Date(config.date+'T10:00')-new Date(r.occurred)>7200000?'首报超时':'待首报')],auditRectify:[esc(r.source),(r.plan?.length||0)+'项计划'],procurement:[esc(r.srm),esc(r.node)],procurementRectify:[link(r.supervisionId),esc(r.requirements)]})[k];}
    const body=`<div class="aw-context">${esc('OA-L3-'+d.code)} · ${esc(config.company)} · 数据范围：${esc(identities[state.role]?.department)} ${btn('演示时钟与配置','settings')}</div><div class="toolbar"><input id="aw-query" aria-label="搜索审计事项" placeholder="编号、名称、责任人" value="${esc(ui.query)}"><button class="primary" onclick="AuditWorkspace.search()">查询</button>${btn('重置','resetFilter')}<span class="spacer"></span>${btn('新建'+d.name,'create',JSON.stringify(k),'primary',!['buyer','head','owner','audit','manager','legal','custodian','admin'].includes(state.role))}</div><div class="stat-row">${stats}</div>${table(['序号','业务编号','事项名称',...columns,'责任部门/人','期限','状态','操作'],rows.map((r,i)=>[i+1+(ui.page-1)*ui.size,link(r.id),`<button class="table-link" onclick="AuditWorkspace.open('${k}','${r.id}')">${esc(r.title)}</button>`,...values(r),esc(r.department+' / '+r.owner),esc(r.due)+'<small class="aw-deadline">'+esc(deadline(r))+'</small>',badge(r.status),btn('进入工作区','open',`'${k}','${r.id}'`)]))}<div class="pager"><span>共${filtered.length}条 · 第${ui.page}/${max}页</span>${btn('上一页','page','-1','secondary',ui.page===1)}${btn('下一页','page','1','secondary',ui.page===max)}<select aria-label="每页条数" onchange="AuditWorkspace.pageSize(this.value)">${[8,15,30].map(n=>`<option ${ui.size===n?'selected':''}>${n}</option>`).join('')}</select></div>`;
    return shell(body,d.name,'责任事项、业务资料与处理结果',btn('审计工作台','home'));
  }
  function home(){state.page='audit-home';render();}
  function homeView(){const all=Object.values(store.records).flat().filter(visible);const pending=store.tasks.filter(t=>{const r=get(t.key,t.objectId);return r&&visible(r)&&(t.role===state.role||state.role==='manager');});return shell(`<div class="aw-context">演示日期 ${config.date} · ${esc(identities[state.role]?.department)} ${btn('时钟与规则配置','settings')}</div><div class="aw-dashboard">${[['合同与履约','contractReview','条款复核、签署与履约'],['合规与法律','compliance','合规条目与案件进展'],['风险管理','riskQuarter','双源核实、整改与延期'],['审计整改','auditRectify','计划、佐证与销账'],['招采监督','procurement','采购文件审查与异常整改']].map(([g,k,desc])=>`<button class="aw-domain" onclick="go('audit-group-${k}')"><span>${g}</span><strong>${all.filter(r=>defs[r.kind].group===g).length}</strong><p>${desc}</p></button>`).join('')}</div>${panel('我的待办',table(['序号','责任事项','节点','期限','处理'],pending.map((t,i)=>[i+1,esc(t.title),esc(get(t.key,t.objectId).status),esc(t.due),btn('办理','open',`'${t.key}','${t.objectId}'`)])))}${panel('临期与超时跟踪',table(['序号','事项','责任人','期限','提醒'],all.filter(r=>/临期|超期/.test(deadline(r))).map((r,i)=>[i+1,link(r.id)+' '+esc(r.title),esc(r.owner),esc(r.due),badge(deadline(r))])))}`,'审计监督部工作台','合同、风险、审计整改与招采监督');}
  function options(type){if(type==='template')return [{id:'非标准合同',title:'非标准合同（增加法务审查）'},...records('contractTemplate').filter(r=>r.status==='已生效'&&visible(r))];if(type==='contract'||type==='approvedContract'||type==='signedContract')return records('contractReview').filter(r=>visible(r)&&(type==='contract'||type==='approvedContract'&&r.status==='已批准'||type==='signedContract'&&r.status==='已签署'));if(type==='risk')return store.risks.filter(r=>visible(r)&&['已确认','整改中'].includes(r.status));if(type==='supervision')return records('procurement').filter(visible);return [];}
  function field(f,r){const [key,label,type='text',choices='',required=true]=f;const val=r[key]??'';let control;if(type==='textarea')control=`<textarea name="${key}" ${required?'required':''}>${esc(val)}</textarea>`;else if(type==='select'||['template','contract','approvedContract','signedContract','risk','supervision'].includes(type)){const opts=type==='select'?choices.split('|').map(v=>({id:v,title:v})):options(type);control=`<select name="${key}" ${required?'required':''}><option value="">请选择</option>${opts.map(o=>`<option value="${esc(o.id)}" ${String(val)===String(o.id)?'selected':''}>${esc(o.title||o.id)}${o.title!==o.id?' · '+esc(o.id):''}</option>`).join('')}</select>`;}else control=`<input name="${key}" type="${type}" ${type==='number'?'min="0" step="0.01"':''} value="${esc(val)}" ${required?'required':''}>`;return `<label class="aw-field ${type==='textarea'?'wide':''}"><span>${esc(label)}${required?' *':''}</span>${control}</label>`;}
  function create(k){if(!['buyer','head','owner','audit','manager','legal','custodian','admin'].includes(state.role))return toast('当前身份没有该类事项的新建权限');if(k==='riskFeedback'){toast('请选择已下发的整改单提交反馈');return;}ui.key=k;ui.id=null;ui.draft={title:'',company:config.company,department:identities[state.role].department,owner:currentRole().name,due:'2026-08-30',version:'V1.0'};state.page='audit-edit';render();}
  function edit(){const r=record();if(!r||!canEdit(r)||!['草稿','已退回','待分派'].includes(r.status)){toast('当前状态不能修改业务资料');return;}ui.draft=clone(r);state.page='audit-edit';render();}
  function editView(){const d=defs[ui.key],r=ui.draft;return shell(`${btn('返回','cancelEdit')}<form id="aw-form" onsubmit="event.preventDefault();AuditWorkspace.save()">${panel('责任与范围',`<div class="aw-form">${field(['title','事项名称'],r)}${field(['company','公司主体','select',config.company],r)}${field(['department','责任部门','select',identities[state.role].all?'采购部|生产管理部|党政综合办|审计监督部|法务合规岗':identities[state.role].department],r)}${field(['owner','责任人'],r)}${field(['due','完成期限','date'],r)}</div>`)}${panel(d.name+' · 业务资料',`<div class="aw-form">${d.fields.filter(f=>f[0]!=='due').map(f=>field(f,r)).join('')}</div>`)}<div class="aw-sticky"><button type="submit" class="primary">保存业务草稿</button><button type="button" class="secondary" onclick="AuditWorkspace.cancelEdit()">取消</button><span>保存后在工作区补充明细和附件，再提交对应流程。</span></div></form>`,d.name+' · '+(ui.id?'编辑':'新建'),'OA-L3-'+d.code);}
  function cancelEdit(){if(ui.id){state.page='audit-record';render();}else{state.page='audit-'+ui.key;render();}}
  function save(){const form=document.querySelector('#aw-form');if(!form.reportValidity())return;if(!canEdit({...ui.draft,project:config.project}))return toast('当前身份无权保存');const data=Object.fromEntries(new FormData(form));if(new Date(data.due)<new Date(config.date)){toast('完成期限不能早于演示日期');return;}for(const f of defs[ui.key].fields)if(f[2]==='number'){data[f[0]]=Number(data[f[0]]);if(!Number.isFinite(data[f[0]])||data[f[0]]<0){toast('金额或数量无效');return;}}if(data.copies!==undefined&&(!Number.isInteger(data.copies)||data.copies<1)){toast('份数必须为正整数');return;}if(data.effective&&data.reviewDate&&data.reviewDate<data.effective){toast('复审日期不能早于生效日期');return;}if(!visible({...ui.draft,...data,project:config.project}))return toast('责任范围超出授权');for(const f of defs[ui.key].fields){if(['contract','approvedContract','signedContract','risk','supervision','template'].includes(f[2])&&!options(f[2]).some(o=>o.id===data[f[0]]))return toast('关联对象无效或不在授权范围');}if(data.amount!==undefined&&data.amount<=0||data.newAmount!==undefined&&data.newAmount<=0)return toast('合同或案件金额必须大于0');if(data.signedDue&&data.signedDue<config.date)return toast('签署期限不能早于业务日期');let r=record();if(r&&(!canEdit(r)||!['草稿','已退回','待分派'].includes(r.status))){toast('无权编辑');return;}if(!r){r=seed(ui.key,newId(defs[ui.key].prefix),data.title);ui.id=r.id;}Object.assign(r,data);if(!visible(r)){toast('责任范围超出授权');return;}if(r.kind==='contractReview'){r.clauses=r.clauses||[];r.payments=r.payments||[];r.adminConfirmed=false;}if(r.kind==='contractChange'||r.kind==='contractTermination'){const c=get('contractReview',r.contractId);r.before={amount:c.amount,scope:c.businessScope,payment:c.paymentTerms,version:c.version};}if(r.kind==='procurementRectify'){const p=get('procurement',r.supervisionId);r.srm=p.srm;}log(r,'保存业务资料','专属字段已保存');task(r);state.page='audit-record';render();}
  function flow(r){const steps=defs[r.kind].steps;let idx=steps.indexOf(r.status);return `<div class="aw-flow">${steps.map((s,i)=>`<div class="${i===idx?'current':idx>i?'done':''}"><span>${i+1}</span><b>${s}</b><small>${(approvedRole(s).map(k=>roles[k]?.label)[0])||(/整改|履约/.test(s)?r.owner:'经办人')}</small></div>`).join('')}</div>${r.status==='已退回'?'<div class="aw-warning">已退回，请根据处理意见修改后重新提交。</div>':''}`;}
  function detail(){const r=record(),d=defs[ui.key];if(!r||!visible(r))return shell('<div class="empty">当前身份无权查看该事项。</div>','访问范围提示','',btn('返回台账','back'));const tabs=['业务详情','附件资料','审批与操作记录'];const basic=`<div class="aw-record-head"><div><span>OA-L3-${d.code} · ${esc(r.id)}</span><h2>${esc(r.title)}</h2><p>${esc(r.company)} / ${esc(r.department)} · ${esc(r.owner)} · 截止 ${esc(r.due)}</p></div><div>${badge(r.status)} ${badge(deadline(r))}</div></div>${flow(r)}<div class="tabs">${tabs.map(t=>`<button class="${ui.tab===t?'active':''}" onclick="AuditWorkspace.tab('${t}')">${t}${t==='附件资料'?' '+r.files.length:''}</button>`).join('')}</div>`;
    let content=ui.tab==='附件资料'?attachments(r):ui.tab==='审批与操作记录'?auditView(r):business(r);
    return shell(`<div class="aw-back">${btn('返回来源台账','back')}${['草稿','已退回','待分派'].includes(r.status)?btn('编辑业务资料','edit','', 'secondary',!canEdit(r)):''}</div>${basic}${content}<div class="aw-sticky">${actions(r)}</div>`,d.name,'',btn('演示身份与规则','settings'));
  }
  function business(r){const d=defs[r.kind];const base=panel('业务信息',`<div class="aw-info">${d.fields.map(([key,label])=>['contractId','riskId','supervisionId'].includes(key)?`<div><span>${label}</span>${link(r[key])}</div>`:kv(label,r[key])).join('')}</div>`);let extra='';
    if(r.kind==='contractTemplate'||r.kind==='compliance')extra=clausesView(r)+versions(r);
    if(r.kind==='contractReview')extra=contractView(r);
    if(r.kind==='contractChange')extra=panel('变更前后对照',table(['变更项','原有效值','拟批准值'],[['合同金额',money((r.before||get('contractReview',r.contractId)||{}).amount),money(r.newAmount)],['合同范围',esc(r.before?.scope||get('contractReview',r.contractId)?.businessScope),esc(r.newScope)],['付款安排',esc(r.before?.payment||get('contractReview',r.contractId)?.paymentTerms),esc(r.newPayment)]]));
    if(r.kind==='contractTermination')extra=panel('原合同履约与已付事实',`<div class="aw-info">${kv('原合同状态',get('contractReview',r.contractId)?.status)}${kv('已付款不撤销',records('contractPerformance').filter(p=>p.contractId===r.contractId).flatMap(p=>p.payments||[]).filter(p=>p.status==='已付款').reduce((a,p)=>a+p.amount,0)+'元')}</div>`);
    if(r.kind==='contractSeal')extra=panel('签署与正式文本',`<div class="aw-info">${kv('签署方式',r.signMode)}${kv('签署时间',r.signedAt)}${kv('正式文本回传',r.returnedAt)}${kv('关联合同批准版本',get('contractReview',r.contractId)?.approvedSnapshot?.version)}</div>`);
    if(r.kind==='contractPerformance')extra=planView(r)+panel('付款计划与ERP回传',table(['序号','付款项','金额','状态'],(r.payments||[]).map((p,i)=>[i+1,esc(p.name),money(p.amount),badge(p.status)])),btn('模拟ERP回传','syncDialog',`'ERP','${r.id}'`));
    if(r.kind==='legal')extra=legalView(r);
    if(r.kind==='riskQuarter'){const risk=store.risks.find(x=>x.id===r.riskId);extra=panel('双源核实与人工评估',`<div class="aw-source-grid">${kv('人工来源',r.source)}${kv('AI来源/规则版本',r.aiSource||'尚未关联AI来源')}${kv('业务键',r.businessKey)}${kv('AI建议等级',r.suggestion||'中')}${kv('最终人工等级',r.level)}${kv('核实理由',r.levelReason)}${kv('正式风险编号',r.riskId)}${kv('正式风险状态',risk?.status)}</div>`)+panel('关联整改单',table(['编号','责任人','状态','处理'],records('riskRectify').filter(x=>x.riskId===r.riskId).map(x=>[link(x.id),esc(x.owner),badge(x.status),btn('查看整改','open',`'riskFeedback','${x.id}'`)])));}
    if(['riskRectify','auditRectify','procurementRectify'].includes(r.kind))extra=planView(r)+feedbackView(r)+extensionView(r);
    if(r.kind==='riskEvent')extra=panel('限时报告与续报',`<div class="aw-info">${kv('首报期限',new Date(new Date(r.occurred).getTime()+7200000).toLocaleString('zh-CN'))}${kv('实际首报时间',r.reportedAt)}</div>`)+planView(r)+feedbackView(r);
    if(r.kind==='procurement')extra=procurementView(r);
    return extra+base;
  }
  function versions(r){return panel('历史版本与引用',table(['序号','历史版本','保存时间','变更类型'],r.history.map((x,i)=>[i+1,esc(x.version),esc(x.time),esc(x.operation)])));}
  function clausesView(r){return panel(r.kind==='compliance'?'合规条目 · 识别、评估与防控':'模板条款目录',table(['序号','条款/控制项','制度依据','要求','操作'],(r.clauses||[]).map((c,i)=>[i+1,esc(c.name),esc(c.basis),esc(c.requirement),btn('编辑','editClause',String(i),'secondary',!['草稿','已退回'].includes(r.status))])),btn('新增条目','editClause','-1','secondary',!['草稿','已退回'].includes(r.status)));}
  function contractView(r){return panel('分类评审与意见落实',`<div class="aw-review-strip">${kv('评审路线',r.templateId==='非标准合同'?'非标准合同：强化法务审查':'标准模板：差异条款复核')}${kv('匹配条件',r.company+' / '+r.contractType+' / '+r.partyRole+' / '+r.direction+' / '+money(r.amount))}${kv('合规引用版本',r.complianceVersion||'2026版')}${kv('管理员落实复核',r.adminConfirmed?'已确认':'待确认')}</div><div class="aw-clause-list">${(r.clauses||[]).map((c,i)=>`<article><div class="aw-clause-title"><h3>${esc(c.title||c.no)}</h3>${badge(c.risk+'风险')} ${badge(c.decision)}</div><div class="aw-compare"><div><label>送审条款原文</label><p>${esc(c.text)}</p></div><div><label>AI建议 · 规则辅助</label><p>${esc(c.suggestion)}</p><small>${esc(c.basis||'采购合同控制规则 V1.0')}</small></div></div><p>人工意见：${esc(c.reviewNote||'尚未形成')}</p>${r.status==='人工复核'?btn('形成审核意见','reviewClause',String(i),'primary',!approvedRole(r.status).includes(state.role)):''}</article>`).join('')||'<div class="empty">提交送审后生成模拟条款检查结果。</div>'}</div>`,r.approvedSnapshot?btn('下载批准版PDF','exportPdf'):'' )+versions(r);}
  function planView(r){return panel(r.kind==='contractPerformance'?'履约里程碑':r.kind==='riskEvent'?'责任分派与任务':'整改计划与持续跟踪',table(['序号','计划任务','责任人','期限','状态','处理'],(r.plan||[]).map((p,i)=>[i+1,esc(p.name),esc(p.owner),esc(p.due),badge(p.status),btn('任务反馈','planFeedback',String(i),'secondary',/已关闭|已销账|已归档/.test(r.status))])),btn('新增计划任务','addPlan','', 'secondary',!canEdit(r)||/已关闭|已销账|已归档/.test(r.status)));}
  function feedbackView(r){return panel('阶段反馈与佐证',table(['序号','时间','进度','措施/结果','提交人'],(r.feedback||[]).map((f,i)=>[i+1,esc(f.time),f.progress+'%',esc(f.note),esc(f.actor)])));}
  function extensionView(r){return panel('延期申请与审批',table(['申请编号','原期限','申请期限','理由','审批状态','意见'],store.extensions.filter(e=>e.objectId===r.id).map(e=>[esc(e.id),esc(e.oldDue),esc(e.newDue),esc(e.reason),badge(e.status),esc(e.opinion||'—')])),store.extensions.some(e=>e.objectId===r.id&&e.status==='待审批')&&privileged()?btn('审批延期','extensionReview'): '');}
  function legalView(r){return panel('办案费用',table(['序号','费用类型','金额','凭据说明'],(r.expenses||[]).map((e,i)=>[i+1,esc(e.type),money(e.amount),esc(e.note)])),btn('登记费用','legalExpense'))+panel('协办、开庭与文书',`<div class="aw-info">${kv('承办人',r.handler)}${kv('协办人',r.collaborator)}${kv('开庭日期',r.hearing)}</div>`,btn('协办/开庭安排','legalAssign'))+feedbackView(r);}
  function procurementView(r){return panel('采购文件AI检查与人工审核',table(['序号','审查项','命中证据','建议','人工结论','操作'],(r.findings||[]).map((f,i)=>[i+1,esc(f.name),esc(f.text),esc(f.suggestion),esc(f.decision)+(f.note?'<p>'+esc(f.note)+'</p>':''),btn('人工复核','procurementReview',String(i),'secondary',r.status!=='文件复核'||!approvedRole(r.status).includes(state.role))])))+panel('项目变更与监督意见',table(['时间','变更事项','影响与监督结论'],(r.changes||[]).map(c=>[esc(c.time),esc(c.title),esc(c.note)])),btn('登记项目变更','procurementChange'))+panel('合同交底与异常整改',`<div class="aw-info"><div><span>关联采购合同</span>${link(r.contractId)}</div>${kv('合同交底',r.handover?'已完成':'待办理')}${kv('最新SRM节点',r.node)}</div>${table(['异常编号','整改要求','状态'],records('procurementRectify').filter(x=>x.supervisionId===r.id).map(x=>[link(x.id),esc(x.requirements),badge(x.status)]))}`,btn('合同交底','handover')+btn('下发异常整改','procurementIssue')+btn('模拟SRM回传','syncDialog',`'SRM','${r.id}'`));}
  function attachments(r){return panel('附件与业务版本',`<div class="aw-upload"><label>资料分类<select id="aw-file-category"><option>参考材料</option><option>整改佐证</option><option>正式签署版</option><option>法律文书</option><option>修改版</option></select></label><label>版本<input id="aw-file-version" value="${esc(r.version)}"></label><label>选择本地文件<input type="file" id="aw-file" onchange="AuditWorkspace.upload(this.files[0])" ${!canEdit(r)?'disabled':''}></label></div>${table(['序号','资料名称','分类','版本','上传人/时间','操作'],r.files.map((f,i)=>[i+1,esc(f.name)+(f.sample?' <small>演示样例</small>':''),esc(f.category),esc(f.version),esc(f.uploader)+'<small>'+esc(f.time)+'</small>',btn('预览','file',`${i},true`)+btn('下载','file',`${i},false`)]))}`);}
  function auditView(r){return `<div class="aw-context">流程实例 ${esc(r.flowId||'WF-'+r.id)} · 当前节点 ${esc(r.status)}</div>`+panel('审批处理记录',table(['时间','节点','人员','结论','意见'],(r.reviews||[]).map(x=>[esc(x.time),esc(x.node),esc(x.actor),badge(x.result),esc(x.note)])))+panel('操作留痕',table(['时间','人员','操作','结果'],r.audit.map(x=>[esc(x.time),esc(x.actor),esc(x.action),esc(x.result)])));}
  function actions(r){let a='';const terminal=/已关闭|已销账|已归档|已终止/.test(r.status);if(['contractTemplate','compliance'].includes(r.kind)&&r.status==='已生效')return btn('发起修订','revise',"'修订'")+btn(r.kind==='compliance'?'发起复审':'申请停用','revise',r.kind==='compliance'?"'复审'":"'停用'");if(terminal)return '<span>已办结 · 历史记录与业务证据可回看</span>';
    if(['草稿','已退回'].includes(r.status))a+=btn('提交'+(r.kind==='riskEvent'?'首报':'审核'),'act',"'submit'",'primary',!canEdit(r));
    if(approvedRole(r.status).includes(state.role))a+=btn(r.status==='待评估'?'核实并确认风险等级':r.status==='管理员复核'?'确认意见落实并提交':r.status==='人工复核'||r.status==='文件复核'?'提交复核结果':'审核通过','act',"'approve'",'primary')+btn('退回修改','act',"'reject'");
    if(r.kind==='riskQuarter'&&r.status==='已确认')a+=btn('配置并下发整改单','issueRisk','', 'primary',!privileged());
    if(['riskRectify','auditRectify','procurementRectify'].includes(r.kind)){if(r.status==='待分派')a+=btn('下发责任任务','act',"'assign'",'primary',!privileged());if(r.status==='整改中')a+=btn('提交阶段反馈','feedback')+btn('申请延期','extension')+btn('提交审计复核','act',"'review'",'primary');if(r.status==='待复核')a+=btn('复核通过并销账','act',"'close'",'primary',!privileged())+btn('退回整改','act',"'return'",'secondary',!privileged());a+=btn('催办并留痕','act',"'remind'",'secondary',!privileged());}
    if(r.kind==='contractSeal'&&r.status==='待签署')a+=btn('登记'+r.signMode+'结果','act',"'sign'",'primary');if(r.kind==='contractSeal'&&r.status==='待回传')a+=btn('确认正式文本回传归档','act',"'sealReturn'",'primary');
    if(r.kind==='contractPerformance'&&r.status==='履约中')a+=btn('提交履约关闭','act',"'performanceClose'",'primary');
    if(r.kind==='legal'&&r.status==='处理中')a+=btn('追加案件进展','feedback')+btn('提交结案','act',"'caseClose'",'primary');
    if(r.kind==='riskEvent'&&r.status==='持续跟踪')a+=btn('提交续报','feedback')+btn('提交办结','act',"'eventClose'",'primary');
    if(r.kind==='procurement'&&r.status==='监督中')a+=btn('监督结果归档','act',"'procurementClose'",'primary');return a;
  }
  function modal(title,fields,cb,initial={}){const actor=state.role,object=record(),status=object?.status;ui.modalCallback=v=>{if(state.role!==actor||object&&object.status!==status){toast('身份或节点已变化，请重新打开操作');return false;}return cb(v);};openModal(title,`<form id="aw-action-form"><div class="aw-form">${fields.map(f=>field(f,initial)).join('')}</div></form>`,btn('取消','closeDialog')+btn('确认提交','submitDialog','','primary'));}
  function submitDialog(){const f=document.querySelector('#aw-action-form');if(!f.reportValidity())return;const data=Object.fromEntries(new FormData(f));const cb=ui.modalCallback;if(cb&&cb(data)!==false){closeModal();render();}}
  function check(r){if(!r||!visible(r)||!canEdit(r)){toast('当前身份无权办理此事项');return false;}return true;}
  function act(action){const r=record();if(!check(r))return;if(action==='approve'&&r.status==='待评估')return assess();modal(action==='approve'?'审核结论':action==='reject'||action==='return'?'退回意见':'业务处理意见',[['note','处理意见','textarea']],({note})=>transition(r,action,note));}
  function transition(r,action,note){if(!check(r))return false;const fail=s=>{toast(s);return false;};const old=r.status,d=defs[r.kind];
    if(action==='submit'){if(!['草稿','已退回'].includes(old))return fail('不能重复提交');if(['contractTemplate','compliance'].includes(r.kind)&&!r.clauses?.length)return fail('请先维护至少一项条款或合规控制');if(r.kind==='contractReview'){if(!r.body||!r.party||!r.amount)return fail('请完善合同正文、相对方与金额');if(r.templateId!=='非标准合同'&&get('contractTemplate',r.templateId)?.status!=='已生效')return fail('模板已停用或无效');if(!r.clauses.length)r.clauses=[{no:'第一条',title:'付款与验收',text:r.body,suggestion:'明确验收条件、付款时点和违约责任。',basis:'合同控制规则 V1.0',risk:'中',decision:'待复核'}];r.clauses.forEach(c=>{c.decision='待复核';c.reviewNote='';});r.adminConfirmed=false;}
      if(r.kind==='procurement'){r.changes=r.changes||[];if(!r.findings?.length)r.findings=[{name:'采购文件资格与履约控制',text:r.document,suggestion:'核实资质有效期、评标归档与履约条件',decision:'待复核',note:''}];r.ruleVersion='PROC-CHECK-V1.0';}
      if(r.kind==='contractSeal'){const c=get('contractReview',r.contractId);if(!c||c.status!=='已批准')return fail('仅可为已批准合同申请用印');}
      if(['contractChange','contractTermination'].includes(r.kind)){const c=get('contractReview',r.contractId);if(!c||!['已批准','已签署'].includes(c.status))return fail('原合同须已批准或已签署且未终止');if(r.kind==='contractChange'&&(!Number.isFinite(Number(r.newAmount))||Number(r.newAmount)<=0))return fail('变更金额必须大于0');}
      r.status=d.steps[1];if(r.kind==='riskEvent')r.reportedAt=now();
    }else if(action==='approve'){if(!approvedRole(old).includes(state.role))return fail('当前身份不是本节点处理人');if(old==='待评估')return fail('请通过风险核实表确认人工等级');if(old==='人工复核'&&r.clauses.some(c=>c.decision==='待复核'))return fail('仍有合同条款未形成人工意见');if(old==='文件复核'&&(r.findings||[]).some(c=>c.decision==='待复核'))return fail('请逐项完成采购文件复核');if(old==='管理员复核'){if(!r.files.some(f=>f.category==='修改版'))return fail('请上传或生成修改版以复核意见落实');r.adminConfirmed=true;}if(r.kind==='contractReview'&&old==='待批准'&&!r.adminConfirmed)return fail('合同管理员尚未确认意见落实');const idx=d.steps.indexOf(old);r.status=d.steps[idx+1]||old;onApproved(r,old);
    }else if(action==='reject'){if(!approvedRole(old).includes(state.role))return fail('无权退回');r.status='已退回';}
    else if(action==='assign'){if(!privileged()||old!=='待分派')return fail('仅审计/管理层可下发待分派事项');if(!r.requirements||!r.acceptance||!r.owner||!r.due)return fail('请补齐责任、期限、要求和验收标准');r.status='整改中';}
    else if(action==='review'){if(old!=='整改中')return fail('当前不能提交复核');if(!r.plan.length||r.plan.some(p=>p.status!=='已完成')||r.progress!==100||!r.feedback.length||!r.files.some(f=>f.category==='整改佐证'))return fail('需完成全部计划、100%反馈并提供整改佐证');if(r.returnFeedbackCount!==undefined&&r.feedback.length<=r.returnFeedbackCount)return fail('退回后需补充新的整改反馈再提交');if(store.extensions.some(e=>e.objectId===r.id&&e.status==='待审批'))return fail('请先完成延期审批');r.status='待复核';}
    else if(action==='close'){if(!privileged()||old!=='待复核'||r.progress!==100||!r.files.some(f=>f.category==='整改佐证'))return fail('必须完成整改并经审计复核');r.status=r.kind==='riskRectify'?'已关闭':'已销账';}
    else if(action==='return'){if(!privileged()||old!=='待复核')return fail('当前不能退回整改');r.status='整改中';r.returnFeedbackCount=r.feedback.length;}
    else if(action==='remind'){if(!privileged())return fail('当前身份无权催办');db.messages.unshift({id:newId('MSG'),title:r.title+'：'+note,time:now(),read:false,objectId:r.id});}
    else if(action==='sign'){if(old!=='待签署')return fail('尚未通过用印审批');r.signedAt=now();r.status='待回传';}
    else if(action==='sealReturn'){if(old!=='待回传'||!r.files.some(f=>f.category==='正式签署版'))return fail('请上传正式签署版后回传');r.returnedAt=now();r.status='已归档';const c=get('contractReview',r.contractId);c.status='已签署';c.files.push(...r.files.filter(f=>f.category==='正式签署版').map(clone));log(c,'签署回传',r.id);if(!records('contractPerformance').some(p=>p.contractId===c.id)){const p=seed('contractPerformance',newId('CTP'),c.title+'履约台账',{contractId:c.id,milestone:'首批交付验收',acceptance:'交付验收单齐备',paymentTerms:c.paymentTerms,plan:[{name:'首批交付验收',owner:c.owner,due:r.due,status:'待办理'}],payments:[{name:'验收付款',amount:c.amount,status:'未付款'}]},'履约中');task(p);}}
    else if(action==='performanceClose'){if(old!=='履约中'||r.plan.some(p=>p.status!=='已完成')||!r.plan.length||(r.payments||[]).some(p=>p.status!=='已付款'))return fail('履约节点及ERP付款结果未全部完成');r.status='已关闭';}
    else if(action==='caseClose'){if(old!=='处理中'||!r.feedback.length||!r.files.some(f=>f.category==='法律文书'))return fail('需案件进展、结案结果及法律文书');r.result=note;r.status='结案审批';}
    else if(action==='eventClose'){if(old!=='持续跟踪'||!r.feedback.length||!r.plan.length||r.plan.some(p=>p.status!=='已完成'))return fail('需完成责任任务并提交续报');r.status='办结审批';}
    else if(action==='procurementClose'){if(old!=='监督中'||!r.handover||records('procurementRectify').some(p=>p.supervisionId===r.id&&p.status!=='已销账'))return fail('需完成合同交底并销账全部关联异常');r.status='已归档';}
    else return fail('不支持的业务动作');
    r.reviews.unshift({time:now(),node:old,actor:currentRole().name,result:r.status,note});log(r,action,old+' → '+r.status+'；'+note);syncRelations(r);task(r);return true;
  }
  function onApproved(r,old){if(r.kind==='contractReview'&&r.status==='已批准'){r.version=(r.files.filter(f=>f.category==='修改版').at(-1)?.version||r.version.replace(/送审稿|草稿/g,''))+'-批准版';r.approvedSnapshot={version:r.version,body:r.clauses.map(c=>c.revised||c.text).join('\n\n'),amount:r.amount};if(!records('contractSeal').some(s=>s.contractId===r.id)){const s=seed('contractSeal',newId('CTS'),r.title+'用印申请',{contractId:r.id,sealType:'合同专用章',copies:2,signMode:'线下签署',signParty:r.party,signedDue:r.signedDue},'草稿');task(s);}}
    if(['contractTemplate','compliance'].includes(r.kind)&&r.status==='已生效'&&r.parentId){const parent=get(r.kind,r.parentId);parent.status=r.operation==='停用'?'已停用':'历史版本';log(parent,'版本替代',r.id+' '+r.version);task(parent);}
    if(r.kind==='contractTemplate'&&r.status==='已生效'&&r.operation==='停用')r.status='已停用';
    if(r.kind==='contractChange'&&r.status==='已生效'){const c=get('contractReview',r.contractId);c.history.unshift({version:c.version,body:c.approvedSnapshot?.body||c.body,amount:c.amount,time:now(),operation:'合同变更前'});c.amount=Number(r.newAmount);c.businessScope=r.newScope;c.paymentTerms=r.newPayment;c.version=r.version;c.approvedSnapshot={version:c.version,body:(c.approvedSnapshot?.body||c.body)+'\n\n批准补充协议 '+r.id+'：'+r.newScope+'；付款计划：'+r.newPayment,amount:c.amount};for(const p of records('contractPerformance').filter(p=>p.contractId===c.id)){p.paymentTerms=r.newPayment;const paid=p.payments.filter(x=>x.status==='已付款').reduce((n,x)=>n+x.amount,0);p.payments=[...p.payments.filter(x=>x.status==='已付款'),{name:'变更后剩余款',amount:Math.max(0,c.amount-paid),status:'未付款'}];log(p,'付款计划变更',r.id);}log(c,'补充协议批准',r.id);}
    if(r.kind==='contractTermination'&&r.status==='已终止'){const c=get('contractReview',r.contractId);c.status='已终止';for(const p of records('contractPerformance').filter(p=>p.contractId===c.id)){p.status='已终止';p.plan.forEach(t=>{if(t.status!=='已完成')t.status='已取消';});task(p);}task(c);log(c,'合同解除/终止',r.id);}
  }
  function syncRelations(r){if(r.riskId){const risk=store.risks.find(x=>x.id===r.riskId);if(risk&&r.kind==='riskRectify'){risk.status=r.status;log(risk,'整改状态回写',r.id+' '+r.status);}}if(r.supervisionId){const s=get('procurement',r.supervisionId);if(s)log(s,'异常整改回写',r.id+' '+r.status);}}
  function revise(operation){const old=record();if(!check(old)||old.status!=='已生效')return;const existing=records(old.kind).find(x=>x.parentId===old.id&&!['已生效','已停用','历史版本'].includes(x.status));if(existing)return open(old.kind,existing.id);const r=seed(old.kind,newId(defs[old.kind].prefix),old.title+' · '+operation,{...clone(old),id:newId(defs[old.kind].prefix),parentId:old.id,operation,version:old.version+'-修订',status:'草稿',history:[{version:old.version,time:now(),operation,body:old.body,clauses:clone(old.clauses)}],audit:[],reviews:[]});log(r,'发起'+operation,'原版本 '+old.id+' 在审批通过前继续有效');ui.id=r.id;edit();}
  function editClause(i){const r=record();if(!check(r)||!['草稿','已退回'].includes(r.status))return;modal('条款与控制要求',[['name','条款/控制项'],['basis','制度依据'],['requirement','识别、评估及控制要求','textarea']],v=>{r.clauses=r.clauses||[];if(i<0)r.clauses.push(v);else r.clauses[i]=v;log(r,'维护条目',v.name);},r.clauses?.[i]||{});}
