  const samples=Array.from({length:20},(_,i)=>({id:'SAMPLE-'+(i+1),delay:i%7,quality:i%4===0,actual:i%7>=4||i%4===0}));
  store.rules=[{id:'RISK-RULE-2026.08.3',status:'已生效',threshold:5,includeQuality:false,effective:'2026-08-01',scope:'供应商交付与质量',source:'ERP/SRM/QMS',feedback:[],samples:clone(samples),audit:[]},{id:'RISK-RULE-2026.08.4-D',status:'草稿',threshold:4,includeQuality:true,effective:config.date,scope:'供应商交付与质量',source:'ERP/SRM/QMS',feedback:[],samples:clone(samples),audit:[]}];
  const score=r=>{let hit=0,tp=0,fp=0,fn=0;for(const s of r.samples){const predicted=s.delay>=r.threshold||(r.includeQuality&&s.quality);if(predicted)hit++;if(predicted&&s.actual)tp++;if(predicted&&!s.actual)fp++;if(!predicted&&s.actual)fn++;}return {hit,tp,fp,fn,rate:hit?(100*tp/hit).toFixed(1)+'%':'—'};};
